typedef unsigned char MENU_UINT8;

struct MenuColor {
    MENU_UINT8 r;
    MENU_UINT8 g;
    MENU_UINT8 b;
    MENU_UINT8 a;
};

struct nglQuadVertex {
    float X;
    float Y;
    float U;
    float V;
    unsigned int Color;
};

struct nglTexture;

struct nglQuad {
    nglQuadVertex Verts[4];
    float Z;
    unsigned int MapFlags;
    unsigned int BlendMode;
    unsigned int BlendModeConstant;
    nglTexture *Tex;
} __attribute__((aligned(16)));

void nglInitQuad(nglQuad *quad);
void nglSetQuadRect(
    nglQuad *quad,
    float x0,
    float y0,
    float x1,
    float y1);
void nglSetQuadColor(nglQuad *quad, unsigned int color);
void nglSetQuadZ(nglQuad *quad, float z);
void nglListAddQuad(nglQuad *quad);

__asm__(".equ nglInitQuad__FP7nglQuad, 0x003A6920");
__asm__(".equ nglSetQuadRect__FP7nglQuadffff, 0x003A6A68");
__asm__(".equ nglSetQuadColor__FP7nglQuadUi, 0x003A69E8");
__asm__(".equ nglSetQuadZ__FP7nglQuadf, 0x003A6A90");
__asm__(".equ nglListAddQuad__FP7nglQuad, 0x003A67F0");

#define NGL_RGBA32(r,g,b,a) \
    (((int)((r) + 1) >> 1) \
     | (((int)((g) + 1) >> 1) << 8) \
     | (((int)((b) + 1) >> 1) << 16) \
     | (((int)((a) + 1) >> 1) << 24))

void MENU_DrawRect( int x0, int y0, int x1, int y1, const MenuColor &color )
{
	nglQuad q;
	nglInitQuad( &q );
	nglSetQuadRect( &q, x0, y0, x1, y1 );
	nglSetQuadColor(&q, NGL_RGBA32(color.r, color.g, color.b, color.a));
	nglSetQuadZ( &q, 1.0f );
	nglListAddQuad( &q );
}
